import type { CommentFetchResult } from './types'

const LINKEDIN_API_BASE = 'https://api.linkedin.com/v2'
const LINKEDIN_VERSION = '202312'

async function fetchLinkedInJson(url: string, accessToken: string): Promise<Record<string, unknown>> {
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'LinkedIn-Version': LINKEDIN_VERSION,
      'X-Restli-Protocol-Version': '2.0.0',
    },
  })

  const text = await response.text()
  let payload: Record<string, unknown> = {}
  try {
    payload = text ? (JSON.parse(text) as Record<string, unknown>) : {}
  } catch {
    payload = {}
  }

  if (!response.ok) {
    const message =
      (typeof payload.message === 'string' && payload.message) ||
      text ||
      `HTTP ${response.status}`
    throw new Error(`LinkedIn API error: ${message}`)
  }

  return payload
}

interface RawLinkedInComment {
  id?: string
  message?: { text?: string }
  actor?: string                 // URN like "urn:li:person:XXXX"
  created?: { time?: number }
}

function extractPersonId(actorUrn: string | undefined): string {
  if (!actorUrn) return 'unknown'
  const parts = actorUrn.split(':')
  return parts[parts.length - 1] ?? actorUrn
}

export async function fetchLinkedInComments(params: {
  accessToken: string
  postUrn?: string
  limit?: number
}): Promise<CommentFetchResult> {
  const postUrn = params.postUrn ?? ''
  const empty: CommentFetchResult = {
    platform: 'LINKEDIN',
    postUrl: postUrn
      ? `https://www.linkedin.com/feed/update/${encodeURIComponent(postUrn)}/`
      : 'https://www.linkedin.com',
    comments: [],
  }

  if (!postUrn) return empty

  try {
    const limit = params.limit ?? 50
    const encodedUrn = encodeURIComponent(postUrn)
    const url =
      `${LINKEDIN_API_BASE}/socialActions/${encodedUrn}/comments` +
      `?count=${limit}`

    const payload = await fetchLinkedInJson(url, params.accessToken)
    const rawElements = Array.isArray(payload.elements)
      ? (payload.elements as RawLinkedInComment[])
      : []

    const comments = rawElements.flatMap((el): CommentFetchResult['comments'] => {
      const text = el.message?.text
      if (!el.id || !text) return []
      return [
        {
          commentId: el.id,
          text,
          authorName: extractPersonId(el.actor),
          authorHandle: el.actor,
          createdAt: el.created?.time
            ? new Date(el.created.time).toISOString()
            : undefined,
        },
      ]
    })

    return {
      ...empty,
      postUrl: `https://www.linkedin.com/feed/update/${encodeURIComponent(postUrn)}/`,
      comments,
    }
  } catch {
    return empty
  }
}

import type { CommentFetchResult } from './types'

const TIKTOK_API_BASE = 'https://open.tiktokapis.com/v2'

async function fetchTikTokJson(url: string, accessToken: string): Promise<Record<string, unknown>> {
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
  })

  const text = await response.text()
  let payload: Record<string, unknown> = {}
  try {
    payload = text ? (JSON.parse(text) as Record<string, unknown>) : {}
  } catch {
    payload = {}
  }

  if (!response.ok) {
    const errObj =
      payload.error && typeof payload.error === 'object'
        ? (payload.error as Record<string, unknown>)
        : {}
    const message =
      (typeof errObj.message === 'string' && errObj.message) ||
      text ||
      `HTTP ${response.status}`
    throw new Error(`TikTok API error: ${message}`)
  }

  return payload
}

interface RawTikTokComment {
  id?: string
  text?: string
  like_count?: number
  create_time?: number
  username?: string
}

export async function fetchTikTokComments(params: {
  accessToken: string
  videoId: string
  limit?: number
}): Promise<CommentFetchResult> {
  const postUrl = `https://www.tiktok.com/@video/video/${params.videoId}`
  const empty: CommentFetchResult = {
    platform: 'TIKTOK',
    postUrl,
    comments: [],
  }

  if (!params.videoId) return empty

  try {
    const maxCount = Math.min(params.limit ?? 50, 100)
    const fields = 'id,text,like_count,create_time,username'
    const url =
      `${TIKTOK_API_BASE}/video/comment/list/` +
      `?fields=${encodeURIComponent(fields)}` +
      `&video_id=${encodeURIComponent(params.videoId)}` +
      `&max_count=${maxCount}`

    const payload = await fetchTikTokJson(url, params.accessToken)

    // TikTok wraps response in { data: { comments: [...] } }
    const dataObj =
      payload.data && typeof payload.data === 'object'
        ? (payload.data as Record<string, unknown>)
        : {}

    const rawComments = Array.isArray(dataObj.comments)
      ? (dataObj.comments as RawTikTokComment[])
      : Array.isArray(payload.comments)
        ? (payload.comments as RawTikTokComment[])
        : []

    const comments = rawComments.flatMap((c): CommentFetchResult['comments'] => {
      if (!c.id || !c.text) return []
      return [
        {
          commentId: c.id,
          text: c.text,
          authorName: c.username ?? 'Unknown',
          authorHandle: c.username ? `@${c.username}` : undefined,
          createdAt: c.create_time
            ? new Date(c.create_time * 1000).toISOString()
            : undefined,
        },
      ]
    })

    return { ...empty, comments }
  } catch {
    return empty
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  RefreshCw,
  PlusCircle,
  MessageSquare,
  Clock,
  CheckCircle2,
  Send,
  XCircle,
  ExternalLink,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import clsx from 'clsx'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CommentDraft {
  id: string
  content: string
  isApproved: boolean
  createdAt: string
}

interface Opportunity {
  id: string
  brandId: string
  platform: string
  postUrl: string
  postTitle: string | null
  postContent: string | null
  commentId: string | null
  commentText: string | null
  authorName: string | null
  authorHandle: string | null
  isOwned: boolean
  relevanceNote: string | null
  status: string
  approvedReply: string | null
  postedAt: string | null
  discoveredAt: string
  updatedAt: string
  drafts: CommentDraft[]
}

interface Brand {
  id: string
  name: string
  slug: string
}

interface StatsData {
  pending: number
  draftReady: number
  approved: number
  postedTotal: number
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

type PlatformKey =
  | 'ALL'
  | 'FACEBOOK'
  | 'INSTAGRAM'
  | 'TWITTER'
  | 'LINKEDIN'
  | 'TIKTOK'
  | 'YOUTUBE'
  | 'REDDIT'

const ALL_PLATFORMS: PlatformKey[] = [
  'ALL',
  'FACEBOOK',
  'INSTAGRAM',
  'TWITTER',
  'LINKEDIN',
  'TIKTOK',
  'YOUTUBE',
  'REDDIT',
]

const PLATFORM_LABELS: Record<PlatformKey, string> = {
  ALL: 'All',
  FACEBOOK: 'Facebook',
  INSTAGRAM: 'Instagram',
  TWITTER: 'Twitter / X',
  LINKEDIN: 'LinkedIn',
  TIKTOK: 'TikTok',
  YOUTUBE: 'YouTube',
  REDDIT: 'Reddit',
}

const STATUS_FILTER_OPTIONS = [
  { value: '', label: 'All Statuses' },
  { value: 'PENDING', label: 'Pending' },
  { value: 'DRAFT_READY', label: 'Draft Ready' },
  { value: 'APPROVED', label: 'Approved' },
  { value: 'POSTED', label: 'Posted' },
  { value: 'SKIPPED', label: 'Skipped' },
]

const STATUS_STYLES: Record<string, string> = {
  PENDING: 'bg-yellow-500/15 text-yellow-400 border border-yellow-500/20',
  DRAFT_READY: 'bg-blue-500/15 text-blue-400 border border-blue-500/20',
  APPROVED: 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/20',
  POSTED: 'bg-slate-500/15 text-slate-400 border border-slate-600/30',
  SKIPPED: 'bg-slate-700/40 text-slate-500 border border-slate-700/30',
}

const STATUS_LABELS: Record<string, string> = {
  PENDING: 'Pending',
  DRAFT_READY: 'Draft Ready',
  APPROVED: 'Approved',
  POSTED: 'Posted',
  SKIPPED: 'Skipped',
}

const PLATFORM_DOT_COLORS: Record<string, string> = {
  FACEBOOK: 'bg-blue-500',
  INSTAGRAM: 'bg-pink-500',
  TWITTER: 'bg-sky-400',
  LINKEDIN: 'bg-blue-600',
  TIKTOK: 'bg-slate-300',
  YOUTUBE: 'bg-red-500',
  REDDIT: 'bg-orange-500',
}

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

function truncate(str: string | null | undefined, maxLen: number): string {
  if (!str) return ''
  return str.length > maxLen ? str.slice(0, maxLen) + 'â€¦' : str
}

function formatRelative(dateStr: string): string {
  const diffMs = Date.now() - new Date(dateStr).getTime()
  const mins = Math.floor(diffMs / 60_000)
  if (mins < 1) return 'just now'
  if (mins < 60) return `${mins}m ago`
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return `${hrs}h ago`
  return `${Math.floor(hrs / 24)}d ago`
}

// ---------------------------------------------------------------------------
// Add URL modal
// ---------------------------------------------------------------------------

interface AddUrlModalProps {
  brandId: string
  onClose: () => void
  onAdded: () => void
}

function AddUrlModal({ brandId, onClose, onAdded }: AddUrlModalProps) {
  const [platform, setPlatform] = useState<string>('FACEBOOK')
  const [postUrl, setPostUrl] = useState('')
  const [relevanceNote, setRelevanceNote] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError(null)
    setSubmitting(true)
    try {
      const res = await fetch('/api/comments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          brandId,
          platform,
          postUrl,
          relevanceNote: relevanceNote.trim() || undefined,
        }),
      })
      const json = await res.json()
      if (!json.success) throw new Error(json.error ?? 'Failed to add URL')
      onAdded()
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 w-full max-w-md shadow-2xl">
        <h2 className="text-white font-semibold text-base mb-5">Monitor a Post URL</h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-slate-400 mb-1.5">Platform</label>
            <select
              value={platform}
              onChange={(e) => setPlatform(e.target.value)}
              className="w-full bg-slate-700 border border-slate-600 text-white text-sm rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              {ALL_PLATFORMS.filter((p) => p !== 'ALL').map((p) => (
                <option key={p} value={p}>
                  {PLATFORM_LABELS[p]}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 mb-1.5">Post URL</label>
            <input
              type="url"
              value={postUrl}
              onChange={(e) => setPostUrl(e.target.value)}
              required
              placeholder="https://..."
              className="w-full bg-slate-700 border border-slate-600 text-white text-sm rounded-md px-3 py-2 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 mb-1.5">
              Relevance Note{' '}
              <span className="text-slate-600 font-normal">(optional)</span>
            </label>
            <textarea
              value={relevanceNote}
              onChange={(e) => setRelevanceNote(e.target.value)}
              rows={2}
              placeholder="Why is this post relevant?"
              className="w-full bg-slate-700 border border-slate-600 text-white text-sm rounded-md px-3 py-2 placeholder-slate-500 resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {error && (
            <p className="text-red-400 text-xs bg-red-500/10 border border-red-500/20 rounded px-3 py-2">
              {error}
            </p>
          )}

          <div className="flex gap-2 pt-1">
            <button type="button" onClick={onClose} className="flex-1 btn-secondary">
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || !postUrl.trim()}
              className="flex-1 btn-primary"
            >
              {submitting ? 'Addingâ€¦' : 'Add URL'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Opportunity card
// ---------------------------------------------------------------------------

interface OpportunityCardProps {
  opportunity: Opportunity
  onStatusChange: (id: string, status: string) => Promise<void>
  onDelete: (id: string) => Promise<void>
}

function OpportunityCard({ opportunity, onStatusChange, onDelete }: OpportunityCardProps) {
  const [busy, setBusy] = useState(false)

  async function act(fn: () => Promise<void>) {
    setBusy(true)
    try {
      await fn()
    } finally {
      setBusy(false)
    }
  }

  const dotColor = PLATFORM_DOT_COLORS[opportunity.platform] ?? 'bg-slate-500'
  const platformLabel =
    PLATFORM_LABELS[opportunity.platform as PlatformKey] ?? opportunity.platform

  const isActionable =
    opportunity.status !== 'SKIPPED' && opportunity.status !== 'POSTED'

  return (
    <div className="bg-slate-800 border border-slate-700 rounded-lg p-4 flex flex-col gap-3 hover:border-slate-600 transition-colors">
      {/* Header row */}
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <span className={clsx('w-2 h-2 rounded-full flex-shrink-0', dotColor)} />
          <span className="text-xs font-semibold text-white">{platformLabel}</span>
          <span
            className={clsx(
              'text-xs px-2 py-0.5 rounded-full font-medium flex-shrink-0',
              opportunity.isOwned
                ? 'bg-emerald-500/15 text-emerald-400'
                : 'bg-slate-600/40 text-slate-400'
            )}
          >
            {opportunity.isOwned ? 'Owned' : 'External'}
          </span>
        </div>

        <span
          className={clsx(
            'text-xs px-2 py-0.5 rounded-full font-medium flex-shrink-0',
            STATUS_STYLES[opportunity.status] ?? STATUS_STYLES.PENDING
          )}
        >
          {STATUS_LABELS[opportunity.status] ?? opportunity.status}
        </span>
      </div>

      {/* Post info */}
      {(opportunity.postTitle || opportunity.postContent) && (
        <div className="text-xs text-slate-400 leading-relaxed space-y-0.5">
          {opportunity.postTitle && (
            <p className="font-medium text-slate-300">
              {truncate(opportunity.postTitle, 80)}
            </p>
          )}
          {opportunity.postContent && (
            <p>{truncate(opportunity.postContent, 120)}</p>
          )}
        </div>
      )}

      {/* Comment blockquote */}
      {opportunity.commentText && (
        <blockquote className="border-l-2 border-blue-500/30 pl-3 text-xs text-slate-300 italic leading-relaxed">
          {truncate(opportunity.commentText, 200)}
        </blockquote>
      )}

      {/* Author */}
      {opportunity.authorName && (
        <p className="text-xs text-slate-500">
          <span className="text-slate-400">{opportunity.authorName}</span>
          {opportunity.authorHandle && (
            <span className="ml-1 text-slate-600">({opportunity.authorHandle})</span>
          )}
        </p>
      )}

      {/* Relevance */}
      {opportunity.relevanceNote && (
        <p className="text-xs text-amber-400/80 bg-amber-500/5 border border-amber-500/10 rounded px-2.5 py-2 leading-relaxed">
          {opportunity.relevanceNote}
        </p>
      )}

      {/* Footer */}
      <div className="flex items-center justify-between gap-2 pt-1 border-t border-slate-700/50">
        <span className="text-xs text-slate-600">{formatRelative(opportunity.discoveredAt)}</span>

        <div className="flex items-center gap-1">
          {/* Open post link */}
          <a
            href={opportunity.postUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="p-1.5 text-slate-600 hover:text-slate-300 transition-colors rounded"
            title="Open post"
          >
            <ExternalLink size={13} />
          </a>

          {/* Skip */}
          {isActionable && (
            <button
              onClick={() => act(() => onStatusChange(opportunity.id, 'SKIPPED'))}
              disabled={busy}
              title="Skip"
              className="p-1.5 text-slate-600 hover:text-red-400 transition-colors rounded disabled:opacity-30"
            >
              <XCircle size={13} />
            </button>
          )}

          {/* Mark posted (for APPROVED) */}
          {opportunity.status === 'APPROVED' && (
            <button
              onClick={() => act(() => onStatusChange(opportunity.id, 'POSTED'))}
              disabled={busy}
              title="Mark as posted"
              className="p-1.5 text-slate-600 hover:text-emerald-400 transition-colors rounded disabled:opacity-30"
            >
              <Send size={13} />
            </button>
          )}

          {/* Reply CTA */}
          <a
            href={`/comments/${opportunity.id}`}
            className="text-xs px-2.5 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-md font-medium transition-colors"
          >
            Reply
          </a>

          {/* Delete */}
          <button
            onClick={() => act(() => onDelete(opportunity.id))}
            disabled={busy}
            title="Remove"
            className="p-1.5 text-slate-700 hover:text-red-500 transition-colors rounded disabled:opacity-30"
          >
            <XCircle size={13} />
          </button>
        </div>
      </div>
    </div>
  )
}

