}

// ---------------------------------------------------------------------------
// Main page component
// ---------------------------------------------------------------------------

const PAGE_SIZE = 18

export default function CommentsPage() {
  const [brands, setBrands] = useState<Brand[]>([])
  const [selectedBrandId, setSelectedBrandId] = useState<string>('')
  const [opportunities, setOpportunities] = useState<Opportunity[]>([])
  const [stats, setStats] = useState<StatsData>({
    pending: 0,
    draftReady: 0,
    approved: 0,
    postedTotal: 0,
  })
  const [activePlatform, setActivePlatform] = useState<string>('ALL')
  const [activeStatus, setActiveStatus] = useState<string>('')
  const [page, setPage] = useState(1)
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(false)
  const [scanning, setScanning] = useState(false)
  const [showAddModal, setShowAddModal] = useState(false)
  const [scanMessage, setScanMessage] = useState<{ text: string; ok: boolean } | null>(null)

  // Load brands
  useEffect(() => {
    fetch('/api/brands')
      .then((r) => r.json())
      .then((json) => {
        const list: Brand[] = json.data ?? []
        setBrands(list)
        if (list.length > 0) setSelectedBrandId(list[0].id)
      })
      .catch(() => {})
  }, [])

  const loadOpportunities = useCallback(async () => {
    if (!selectedBrandId) return
    setLoading(true)
    try {
      const qs = new URLSearchParams({
        brandId: selectedBrandId,
        page: String(page),
        limit: String(PAGE_SIZE),
      })
      if (activePlatform !== 'ALL') qs.set('platform', activePlatform)
      if (activeStatus) qs.set('status', activeStatus)

      const res = await fetch(`/api/comments?${qs.toString()}`)
      const json = await res.json()
      if (json.success) {
        setOpportunities(json.data ?? [])
        setTotal(json.meta?.total ?? 0)
      }
    } catch {
      // swallow
    } finally {
      setLoading(false)
    }
  }, [selectedBrandId, page, activePlatform, activeStatus])

  const loadStats = useCallback(async () => {
    if (!selectedBrandId) return
    try {
      const [pendingJson, draftJson, approvedJson, postedJson] = await Promise.all(
        ['PENDING', 'DRAFT_READY', 'APPROVED', 'POSTED'].map((s) =>
          fetch(`/api/comments?brandId=${selectedBrandId}&status=${s}&limit=1`).then((r) =>
            r.json()
          )
        )
      )
      setStats({
        pending: pendingJson.meta?.total ?? 0,
        draftReady: draftJson.meta?.total ?? 0,
        approved: approvedJson.meta?.total ?? 0,
        postedTotal: postedJson.meta?.total ?? 0,
      })
    } catch {
      // swallow
    }
  }, [selectedBrandId])

  useEffect(() => {
    loadOpportunities()
    loadStats()
  }, [loadOpportunities, loadStats])

  // Reset to page 1 when filters change
  useEffect(() => {
    setPage(1)
  }, [activePlatform, activeStatus, selectedBrandId])

  async function handleScan() {
    if (!selectedBrandId || scanning) return
    setScanning(true)
    setScanMessage(null)
    try {
      const res = await fetch('/api/comments/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ brandId: selectedBrandId }),
      })
      const json = await res.json()
      if (json.success) {
        const { created, platforms } = json.data as { created: number; platforms: string[] }
        setScanMessage({
          ok: true,
          text:
            created > 0
              ? `Found ${created} new opportunit${created !== 1 ? 'ies' : 'y'} across: ${platforms.join(', ')}.`
              : 'Scan complete â€” no new opportunities found.',
        })
        await Promise.all([loadOpportunities(), loadStats()])
      } else {
        setScanMessage({ ok: false, text: json.error ?? 'Scan failed.' })
      }
    } catch {
      setScanMessage({ ok: false, text: 'Scan failed â€” check your platform connections.' })
    } finally {
      setScanning(false)
    }
  }

  async function handleStatusChange(id: string, status: string) {
    try {
      await fetch(`/api/comments/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      })
      await Promise.all([loadOpportunities(), loadStats()])
    } catch {
      // swallow
    }
  }

  async function handleDelete(id: string) {
    if (!confirm('Remove this opportunity?')) return
    try {
      await fetch(`/api/comments/${id}`, { method: 'DELETE' })
      await Promise.all([loadOpportunities(), loadStats()])
    } catch {
      // swallow
    }
  }

  const totalPages = Math.ceil(total / PAGE_SIZE)

  return (
    <div className="min-h-full p-6 space-y-5">
      {/* Header */}
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-xl font-bold text-white">Comment Monitor</h1>
          <p className="text-sm text-slate-400 mt-0.5">
            Surface engagement opportunities and manage replies across all platforms.
          </p>
        </div>

        <div className="flex items-center gap-2 flex-shrink-0">
          <button
            onClick={() => setShowAddModal(true)}
            disabled={!selectedBrandId}
            className="btn-secondary flex items-center gap-1.5 text-sm"
          >
            <PlusCircle size={14} />
            Add URL
          </button>
          <button
            onClick={handleScan}
            disabled={scanning || !selectedBrandId}
            className="btn-primary flex items-center gap-1.5 text-sm"
          >
            <RefreshCw size={14} className={clsx(scanning && 'animate-spin')} />
            {scanning ? 'Scanningâ€¦' : 'Scan Now'}
          </button>
        </div>
      </div>

      {/* Controls row */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Brand selector */}
        <select
          value={selectedBrandId}
          onChange={(e) => setSelectedBrandId(e.target.value)}
          className="bg-slate-800 border border-slate-700 text-white text-sm rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          {brands.map((b) => (
            <option key={b.id} value={b.id}>
              {b.name}
            </option>
          ))}
        </select>

        {/* Status filter */}
        <select
          value={activeStatus}
          onChange={(e) => setActiveStatus(e.target.value)}
          className="bg-slate-800 border border-slate-700 text-white text-sm rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          {STATUS_FILTER_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      {/* Platform tabs */}
      <div className="flex items-center gap-1 flex-wrap border-b border-slate-700/50 pb-1">
        {ALL_PLATFORMS.map((p) => (
          <button
            key={p}
            onClick={() => setActivePlatform(p)}
            className={clsx(
              'px-3 py-1.5 rounded-md text-xs font-medium transition-colors',
              activePlatform === p
                ? 'bg-blue-600 text-white'
                : 'text-slate-400 hover:text-white hover:bg-slate-700'
            )}
          >
            {PLATFORM_LABELS[p]}
          </button>
        ))}
      </div>

      {/* Scan message */}
      {scanMessage && (
        <div
          className={clsx(
            'flex items-center justify-between gap-2 rounded-md px-4 py-2.5 text-sm border',
            scanMessage.ok
              ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-300'
              : 'bg-red-500/10 border-red-500/20 text-red-300'
          )}
        >
          <span>{scanMessage.text}</span>
          <button
            onClick={() => setScanMessage(null)}
            className="text-current opacity-50 hover:opacity-100 text-xs flex-shrink-0"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* Stats */}
      <StatsStrip stats={stats} />

      {/* Grid */}
      {loading ? (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div
              key={i}
              className="h-52 bg-slate-800 border border-slate-700 rounded-lg animate-pulse"
            />
          ))}
        </div>
      ) : opportunities.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 text-center">
          <MessageSquare size={40} className="text-slate-700 mb-4" />
          <p className="text-slate-400 font-medium">No opportunities found</p>
          <p className="text-slate-500 text-sm mt-1 max-w-xs">
            Run a scan or add a post URL manually to start monitoring conversations.
          </p>
        </div>
      ) : (
        <>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {opportunities.map((opp) => (
              <OpportunityCard
                key={opp.id}
                opportunity={opp}
                onStatusChange={handleStatusChange}
                onDelete={handleDelete}
              />
            ))}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between border-t border-slate-700/50 pt-4">
              <p className="text-xs text-slate-500">
                {(page - 1) * PAGE_SIZE + 1}â€“{Math.min(page * PAGE_SIZE, total)} of {total}
              </p>
              <div className="flex items-center gap-1.5">
                <button
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page <= 1}
                  className="p-1.5 rounded text-slate-400 hover:text-white hover:bg-slate-700 disabled:opacity-30 transition-colors"
                >
                  <ChevronLeft size={16} />
                </button>
                <span className="text-xs text-slate-500 w-14 text-center">
                  {page} / {totalPages}
                </span>
                <button
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page >= totalPages}
                  className="p-1.5 rounded text-slate-400 hover:text-white hover:bg-slate-700 disabled:opacity-30 transition-colors"
                >
                  <ChevronRight size={16} />
                </button>
              </div>
            </div>
          )}
        </>
      )}

      {/* Add URL modal */}
      {showAddModal && selectedBrandId && (
        <AddUrlModal
          brandId={selectedBrandId}
          onClose={() => setShowAddModal(false)}
          onAdded={() => {
            loadOpportunities()
            loadStats()
          }}
        />
      )}
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { prisma } from '@/lib/db'
import type { ApiResponse } from '@/types'

const DEFAULT_LIMIT = 20
const MAX_LIMIT = 100

const CreateBodySchema = z.object({
  brandId: z.string().min(1),
  platform: z.string().min(1),
  postUrl: z.string().url(),
  postContent: z.string().optional(),
  commentText: z.string().optional(),
  authorName: z.string().optional(),
  relevanceNote: z.string().optional(),
  isOwned: z.boolean().optional(),
})

export async function GET(request: NextRequest): Promise<NextResponse> {
  try {
    const { searchParams } = request.nextUrl

    const brandId = searchParams.get('brandId')
    if (!brandId) {
      const response: ApiResponse<never> = { success: false, error: 'brandId is required' }
      return NextResponse.json(response, { status: 400 })
    }

    const status = searchParams.get('status') ?? undefined
    const platform = searchParams.get('platform') ?? undefined
    const page = Math.max(1, parseInt(searchParams.get('page') ?? '1', 10))
    const limit = Math.min(
      MAX_LIMIT,
      Math.max(1, parseInt(searchParams.get('limit') ?? String(DEFAULT_LIMIT), 10))
    )

    const where: Record<string, unknown> = { brandId }
    if (status) where.status = status.toUpperCase()
    if (platform) where.platform = platform.toUpperCase()

    const [total, opportunities] = await Promise.all([
      prisma.commentOpportunity.count({ where }),
      prisma.commentOpportunity.findMany({
        where,
        include: { drafts: { orderBy: { createdAt: 'desc' } } },
        orderBy: { discoveredAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
    ])

    const response: ApiResponse<typeof opportunities> = {
      success: true,
      data: opportunities,
      meta: { total, page, limit },
    }
    return NextResponse.json(response)
  } catch (error) {
    const response: ApiResponse<never> = {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to fetch opportunities',
    }
    return NextResponse.json(response, { status: 500 })
  }
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const body: unknown = await request.json()
    const parsed = CreateBodySchema.safeParse(body)

    if (!parsed.success) {
      const response: ApiResponse<never> = {
        success: false,
        error: parsed.error.issues.map((i) => i.message).join(', '),
      }
      return NextResponse.json(response, { status: 400 })
    }

    const {
      brandId,
      platform,
      postUrl,
      postContent,
      commentText,
      authorName,
      relevanceNote,
      isOwned,
    } = parsed.data

    const opportunity = await prisma.commentOpportunity.create({
      data: {
        brandId,
        platform: platform.toUpperCase(),
        postUrl,
        postContent: postContent ?? null,
        commentText: commentText ?? null,
        authorName: authorName ?? null,
        relevanceNote: relevanceNote ?? null,
        isOwned: isOwned ?? false,
        status: 'PENDING',
      },
      include: { drafts: true },
    })

    const response: ApiResponse<typeof opportunity> = {
      success: true,
      data: opportunity,
    }
    return NextResponse.json(response, { status: 201 })
  } catch (error) {
    const response: ApiResponse<never> = {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to create opportunity',
    }
    return NextResponse.json(response, { status: 500 })
  }
}

