const ID_DRIVEN_HINTS: Record<string, { placeholder: string; hint: string }> = {
  LINKEDIN: {
    placeholder: 'Post URL or urn:li:activity:â€¦',
    hint: 'Paste a LinkedIn post URL or its urn:li:activity / share id â€” weâ€™ll pull the comments on that post.',
  },
  TIKTOK: {
    placeholder: 'Video URL or numeric video id',
    hint: 'Paste a TikTok video URL (â€¦/video/123â€¦) or the numeric video id â€” weâ€™ll pull the comments on that video.',
  },
